
import {mountMap,fitCourse,followDemoGroup,toggleDemoRoute,toggleMeasure,getDeviceStatus,showDeviceLocation,stopDeviceLocation} from './round-map.js';

const courses=[{name:'Pinehurst No. 2',place:'North Carolina',lat:35.190,lng:-79.467,target:250},{name:'Pebble Beach Golf Links',place:'California',lat:36.568,lng:-121.950,target:260},{name:'Bandon Dunes',place:'Oregon',lat:43.187,lng:-124.391,target:245},{name:'TPC Sawgrass · Stadium Course',place:'Florida',lat:30.198,lng:-81.394,target:255}];
const images=Array.from({length:18},(_,i)=>'assets/pinehurst/hole-'+String(i+1).padStart(2,'0')+'.jpg');
let course=0,hole=8,selected=8,scenario='normal',minute=0,started=false,ended=false,playing=false,mode='real',zoom=false,timer,toastTimer;
const points=Array.from({length:18},(_,i)=>[95+(i%6)*125,112+Math.floor(i/6)*175+(i%2)*33]);
const statuses={normal:['On pace','Good spacing. Better golf.','Your group is keeping comfortable contact with the group ahead. Enjoy the round.'],gap:['Gap ahead','A little room to catch up.','A sustained gap has opened ahead. Please keep pace when safe. This is a sample pace notification.'],queue:['Waiting on traffic','A queue, not a pace problem.','Groups are waiting at the next tee. Your finish window has shifted; your reward eligibility is unaffected.'],stale:['Tracking stale','Let’s check the connection.','No usable update for five minutes. The group position is an old observation; no pace warning should be issued.']};
const clock=n=>`${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
function progress(id){return Math.min(17.95,Math.max(0,7+(8-id)*.63+minute/14));}
function loc(id){const n=progress(id),i=Math.floor(n),t=n-i,a=points[i],b=points[Math.min(17,i+1)];return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];}
function diagram(){const [x,y]=points[hole-1],box=zoom?`${x-150} ${y-130} 300 260`:'0 0 840 650';return `<svg viewBox="${box}" aria-label="Illustrative course traffic map, not actual hole geography"><defs><pattern id="grass" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M4 8l2-4M20 23l2-3" stroke="white" opacity=".05"/></pattern><pattern id="mow" width="15" height="15" patternUnits="userSpaceOnUse" patternTransform="rotate(30)"><rect width="7" height="15" fill="white" opacity=".06"/></pattern></defs><rect width="840" height="650" fill="#244d3c"/><rect width="840" height="650" fill="url(#grass)"/><path d="M760-20Q640 100 780 250T750 650H900V-20" fill="${course===0?'#a79e76':'#507e77'}" opacity=".6"/><path d="M0 550Q190 460 340 555T840 500" stroke="#c5ceac" stroke-width="6" fill="none" opacity=".22"/>${points.map(([x,y],i)=>`<g class="diagram-hit" role="button" tabindex="0" data-hole="${i+1}" aria-label="Explore hole ${i+1}"><g transform="translate(${x} ${y}) rotate(${i%2?26:-26})"><path d="M-18 60Q-40 25-12-15T0-70Q30-85 28-52T18 10Q40 55 12 65Z" fill="${hole===i+1?'#b5c78a':'#779260'}" stroke="#9db57e" stroke-width="2"/><path d="M-18 60Q-40 25-12-15T0-70Q30-85 28-52T18 10Q40 55 12 65Z" fill="url(#mow)"/><ellipse cy="-57" rx="18" ry="23" fill="#bfd28e"/><ellipse cx="29" cy="-28" rx="8" ry="15" fill="#dccc9e"/></g><circle cx="${x}" cy="${y}" r="${hole===i+1?24:17}" fill="#193e30" stroke="${hole===i+1?'#f0d799':'#adc18d'}" stroke-width="2"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="13" fill="#fff7d8">${i+1}</text></g>`).join('')}${Array.from({length:9},(_,i)=>i+4).map(id=>{const [x,y]=loc(id);return `<g class="diagram-hit" role="button" tabindex="0" data-group="${id}" aria-label="Select group ${id}" transform="translate(${x+25} ${y+27})"><circle r="${selected===id?19:14}" fill="${id===8?'#e4c180':'#f2f1de'}" stroke="#214936" stroke-width="2" ${scenario==='stale'&&id===8?'opacity=".5" stroke-dasharray="3 3"':''}/><text y="4" text-anchor="middle" font-size="10" fill="#244b35">${String(id).padStart(2,'0')}</text></g>`;}).join('')}</svg>`;}
function render(){const c=courses[course],s=statuses[scenario],ownHole=Math.floor(progress(8))+1,finish=510+c.target+(scenario==='queue'?18:scenario==='gap'?10:0),currentGroups=Array.from({length:9},(_,i)=>i+4).filter(id=>Math.floor(progress(id))+1===hole);document.querySelector('#app').innerHTML=`<section class="intro"><div><span class="eyebrow">YOUR ROUND, IN RHYTHM</span><h1>The whole course.<br>A clearer picture.</h1><p>Follow your group. See what’s ahead. Enjoy the walk.</p></div><div class="course-select"><label for="course">EXPLORE A COURSE</label><select id="course">${courses.map((c,i)=>`<option value="${i}" ${i===course?'selected':''}>${c.name}</option>`).join('')}</select><p class="disclaimer">Unofficial demo · no course affiliation</p></div></section><section class="roundbar"><div><strong><span class="dot"></span>${ended?'Your demo round is complete':started?'You’re following Group 08':'A good round starts with a little perspective.'}</strong><p>${started?'4 golfers · 08:30 tee time · simulated positions':'Try a round without an account or location permission.'}</p></div><button class="button" data-action="${ended?'reset':started?'end':'start'}">${ended?'Try another round':started?'End demo round':'Start demo round ↗'}</button></section><section class="stats"><div class="stat"><label>YOUR CURRENT HOLE</label><strong>${String(ownHole).padStart(2,'0')} <small>/ 18</small></strong><small>Group 08 · ${clock(630+minute)} demo time</small></div><div class="stat"><label>EXPECTED FINISH</label><strong>${clock(finish-7)}–${clock(finish+8)}</strong><small>Illustrative window, not a validated forecast</small></div><div class="stat"><label>PACE & TRAFFIC</label><strong>${s[0]}</strong><small>${scenario==='queue'?'Traffic-adjusted · no pace penalty':'Sample traffic-aware guidance'}</small></div><div class="stat"><label>COURSE THANK-YOU</label><strong>$5 <small>demo credit</small></strong><small>Course-funded reward concept</small></div></section><div class="workspace"><section class="mapcard"><div class="maphead"><div><span class="eyebrow">${mode==='flow'?'THE COURSE, IN MOTION':'GEOGRAPHIC OVERVIEW'}</span><h2>${c.name}</h2></div><div class="tabs"><button data-mode="flow" class="${mode==='flow'?'active':''}">Round map</button><button data-mode="real" class="${mode==='real'?'active':''}">OpenStreetMap</button></div></div><div class="mapstage">${mode==='flow'?diagram():`<div id="real-map" style="height:570px;width:100%"></div>`}${mode==='flow'?`<div class="map-overlay"><span class="dot"></span>${playing?'Simulation playing':'Simulation paused'}<small>${zoom?'Hole '+hole+' · focused view':'18-hole illustrative layout · not geographic'}</small></div><div class="map-controls"><button data-action="whole">Whole course</button><button data-action="follow">Follow my group</button></div>`:''}</div><div class="map-note"><span>${mode==='flow'?'● Gold: your group · Ivory: other groups':'Real basemap · pan and zoom to explore'}</span><span>${mode==='flow'?'Synthetic layout and group positions':'Real basemap · DEMO markers follow synthetic routes, not actual holes'}</span></div>${mode==='real'?'<div style="padding:0 18px 15px"><button class="button secondary" data-action="device">Show my location</button> <button class="button secondary" data-action="stop-device">Stop GPS</button> <button class="button secondary" data-action="fit-map">Course overview</button> <button class="button secondary" data-action="follow-map">Follow selected group</button> <button class="button secondary" data-action="route">Toggle demo route</button> <button class="button secondary" data-action="measure">Measure distance</button><p id="geo-status" style="font-size:10px;margin-top:10px">Blue marker: your device, with permission. Other markers: simulated groups. Hole shortcuts below open the illustrative layout until real hole mapping is verified.</p></div>':''}<div class="holes">${points.map((_,i)=>`<button data-hole="${i+1}" class="${hole===i+1?'active':''}" aria-pressed="${hole===i+1}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div class="groups">${Array.from({length:9},(_,i)=>i+4).map(id=>`<button data-group="${id}" class="${selected===id?'active':''}">${id===8?'Your group':'Group'} ${String(id).padStart(2,'0')}</button>`).join('')}</div><div class="notification" role="status">${scenario==='normal'?'✓ Your group is keeping appropriate spacing. No action needed.':s[2]}</div></section><aside class="aside"><article class="card">${course===0?`<img class="photo" src="${images[hole-1]}" alt="Pinehurst No. 2 hole ${hole} aerial preview">`:'<div class="placeholder">⚑<small>Course aerial imagery not added yet</small></div>'}<div class="card-body"><span class="eyebrow">A CLOSER LOOK</span><h2>Hole ${String(hole).padStart(2,'0')}</h2><div class="detail"><span>Demo target</span><strong>${Math.round(c.target/18)} min</strong></div><div class="detail"><span>Simulated traffic</span><strong>${currentGroups.length} groups</strong></div><p>${currentGroups.length?currentGroups.map(id=>'Group '+String(id).padStart(2,'0')).join(' · '):'Clear in this simulation.'}</p><p class="safety">${course===0?'Photo: SkyFox / Pinehurst, from existing demo assets. Commercial licensing remains required.':'Verified hole details and imagery are not yet configured.'}</p></div></article><article class="card"><div class="card-body"><span class="eyebrow">FOLLOWING GROUP ${String(selected).padStart(2,'0')}</span><h2>${selected===8?'Your round brief':'A little context.'}</h2><span class="pill ${scenario}">${selected===8?s[0]:'Simulated group'}</span><div class="detail"><span>Current hole</span><strong>${Math.floor(progress(selected))+1} / 18</strong></div><div class="detail"><span>Last update</span><strong>${scenario==='stale'&&selected===8?'5 min ago · stale':'Demo observation'}</strong></div><p>${selected===8?s[2]:'Anonymous group position shown for this demonstration.'}</p><p class="safety">Map markers never indicate that it is safe to hit.</p></div></article><article class="reward"><span class="eyebrow" style="color:#bdcaaa">THE GOOD PACE CLUB</span><h2>A good round.<br>A little thank-you.</h2><p>Keep appropriate pace when there’s room ahead. Waiting in a queue won’t count against you.</p><strong>SIMULATED $5 CREDIT · NO PAYMENT ISSUED</strong></article></aside></div><section class="scenario"><div><span class="eyebrow">TAKE IT FOR A ROUND</span><h2>What happens when the day changes?</h2><p>Try the controls. Watch groups move. Explore a queue, a pace gap, or a lost connection.</p></div><div><select id="scenario" aria-label="Choose a traffic scenario">${Object.entries({normal:'Normal flow',gap:'Gap opening ahead',queue:'Bottleneck at the next tee',stale:'Tracking interruption'}).map(([k,v])=>`<option value="${k}" ${scenario===k?'selected':''}>${v}</option>`).join('')}</select><div class="timeline"><label for="timeline">Round timeline · ${minute} simulated minutes</label><input id="timeline" type="range" min="0" max="140" step="1" value="${minute}" aria-label="Scrub simulated round time"></div><div class="simulation"><button class="button" data-action="play">${playing?'Ⅱ Pause':'▷ Play round'}</button><button class="button secondary" data-action="step">+5 minutes</button><button class="button secondary" data-action="reset">Reset</button></div></div></section><footer><span>Fairway Flow · Unofficial interactive course demo</span><span>Simulated groups, alerts, timing and rewards. Optional GPS stays on your device. Group sharing is not connected.</span></footer>`;if(mode==='real'){document.querySelector('#geo-status').textContent=getDeviceStatus()+' Hole shortcuts use the illustrative layout until geographic hole mapping is verified.';mountMap(document.querySelector('#real-map'),c,course,selected,minute,scenario==='stale');}}
function stop(){playing=false;clearInterval(timer);}
function toast(text){const el=document.querySelector('#toast');el.className='toast';el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3500);}
document.querySelector('#app').addEventListener('change',e=>{if(e.target.id==='course'){stop();course=+e.target.value;stopDeviceLocation();hole=8;minute=0;mode='real';zoom=false;started=false;ended=false;scenario='normal';render();}if(e.target.id==='scenario'){scenario=e.target.value;render();toast(statuses[scenario][2]);}});
document.querySelector('#app').addEventListener('click',e=>{const b=e.target.closest('button,[data-hole],[data-group]');if(!b)return;if(b.dataset.hole){hole=+b.dataset.hole;mode='flow';zoom=true;}if(b.dataset.group){selected=+b.dataset.group;hole=Math.floor(progress(selected))+1;zoom=true;}if(b.dataset.mode){mode=b.dataset.mode;}switch(b.dataset.action){case 'start':started=true;toast('Demo round started. Select a hole or press Play round.');break;case 'end':stop();stopDeviceLocation();ended=true;document.querySelector('#summary-title').textContent=scenario==='normal'||scenario==='queue'?'A good round. A little credit.':'Your round is ready for review.';document.querySelector('#summary-text').textContent=scenario==='normal'||scenario==='queue'?'You earned a simulated $5 course credit. Waiting on traffic did not affect eligibility. No real credit or payment has been issued.':'A staff review would be needed before approving a reward. This demonstration issues no real credits.';document.querySelector('#summary').showModal();break;case 'play':if(ended){toast('Reset the demo to start another round.');break;}started=true;if(playing)stop();else{playing=true;timer=setInterval(()=>{minute=Math.min(140,minute+1);if(minute===140)stop();render();},1000);}break;case 'step':if(!ended){minute=Math.min(140,minute+5);started=true;}break;case 'reset':stop();stopDeviceLocation();minute=0;started=false;ended=false;scenario='normal';hole=8;selected=8;zoom=false;mode='real';break;case 'device':showDeviceLocation(text=>{const el=document.querySelector('#geo-status');if(el)el.textContent=text;});return;case 'stop-device':stopDeviceLocation();toast('Device GPS stopped.');return;case 'follow-map':followDemoGroup();toast('Following selected demo group. Drag the map to stop following.');return;case 'route':toggleDemoRoute();return;case 'measure':toast(toggleMeasure()?'Distance tool on: tap two points on the map.':'Distance tool off.');return;case 'fit-map':fitCourse();return;case 'whole':zoom=false;break;case 'follow':selected=8;hole=Math.floor(progress(8))+1;zoom=true;break;}render();});document.querySelector('#close-summary').onclick=()=>document.querySelector('#summary').close();render();

window.addEventListener('fairway-select-group',e=>{selected=e.detail.id;hole=Math.floor(progress(selected))+1;render();toast('Group '+String(selected).padStart(2,'0')+' selected. See its details beside the map.');});
document.querySelector('#app').addEventListener('change',e=>{if(e.target.id==='timeline'){minute=Number(e.target.value);render();}});
document.querySelector('#app').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.diagram-hit')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});

window.addEventListener('fairway-map-status',e=>{const el=document.querySelector('#geo-status');if(el)el.textContent=e.detail;});
